    s1tag: `Layunin · Ano ang kinokolekta ng pag-aaral na ito`, s1title: `Bakit kami nagtatanong`,
    s1body: `Ang Adherence Project 2026 ay isang pandaigdigang pag-aaral na sumusukat ng pagsunod sa gamot gamit ang napatunayan na MMAS-8, na binuo ni Dr. Donald E. Morisky.`,
    s2tag: `Boluntaryong Pakikilahok · Ang iyong mga karapatan`, s2title: `Ikaw ang may kontrol`,
    s2body: `Ang pakikilahok ay ganap na boluntaryo. Maaari kang tumigil anumang oras nang walang kahihinatnan.`,
    s3tag: `Privacy ng Data · Anonymization`, s3title: `Ano ang iniimbak namin`,
    s3body: `Ang iyong mga sagot ay naka-imbak nang hindi kilala. Inirerekord namin: ang iyong MMAS-8 na marka, ang iyong tinatayang lokasyon (bansa at lungsod), isang random na session ID, at isang timestamp.`,
    s4tag: `Geolocation · Kontribusyon sa mapa`, s4title: `Ilalagay ka sa mapa`,
